import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, Img } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type HighlightOverlayProps = Record<string, any>;

const HighlightOverlay: React.FC<HighlightOverlayProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  backgroundImage = "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/newspaper.jpeg",
  highlightColor = "#ffff00",
  highlightOpacity = 0.6,
  highlightWidth = 400,
  highlightHeight = 40,
  highlightCornerRadius = 4,
  highlightBlur = 2,
  startX = 10,
  startY = 40,
  moveDuration = 2,
  easeType = "ease-in-out",
}) => {
  // Use a simple font as a fallback/default, though we mainly show images/shapes
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Determine Easing function
  let easingFn = Easing.linear;
  if (easeType === "ease-in") easingFn = Easing.in(Easing.ease);
  else if (easeType === "ease-out") easingFn = Easing.out(Easing.ease);
  else if (easeType === "ease-in-out") easingFn = Easing.inOut(Easing.ease);

  // Animation Timing
  const moveDurationFrames = moveDuration * fps;
  
  // Interpolate Width for the extending effect
  // The highlight extends horizontally from 0 width to highlightWidth
  const animatedWidth = interpolate(frame, [0, moveDurationFrames], [0, highlightWidth], {
    easing: easingFn,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate static position based on Start percentages
  const xPos = (width * startX) / 100;
  const yPos = (height * startY) / 100;

  // Background handling
  const containerBg = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: containerBg }}>
      {/* Background Layer - Replaceable Image */}
      <AbsoluteFill>
        <Img
          src={backgroundImage}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
      </AbsoluteFill>

      {/* Highlight Layer */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: animatedWidth, // Controlled by interpolation
          height: highlightHeight,
          backgroundColor: highlightColor,
          opacity: highlightOpacity,
          borderRadius: highlightCornerRadius,
          filter: `blur(${highlightBlur}px)`,
          mixBlendMode: "multiply", 
          transform: `translate(${xPos}px, ${yPos}px)`,
          transition: "none", 
        }}
      />
    </AbsoluteFill>
  );
};

export default HighlightOverlay;